// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0 || true); // any actor allowed
        amount = bound(amount, 1, type(uint256).max / 2);

        Reverter r = new Reverter();
        vm.deal(address(r), amount);
        vm.prank(address(r));
        c.deposit{value: amount}();

        vm.prank(address(r));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: if the withdrawal call fails, the contract must revert,
        // so caller credit is NOT consumed and contract balance is unchanged.
        assertTrue(
            (ok && c.credit(address(r)) == 0 && address(c).balance == 0) ||
            (!ok && c.credit(address(r)) == amount && address(c).balance == amount)
        );
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

