pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 redeposit, address actor) public {
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        amount = bound(amount, 1, 1e30);
        redeposit = bound(redeposit, 0, amount - 1);

        // first cycle: deposit `amount`, withdraw it fully
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();
        assertEq(address(c).balance, 0);

        // second cycle: deposit a fresh (possibly different) amount d, then withdraw
        vm.deal(actor, redeposit);
        vm.prank(actor);
        c.deposit{value: redeposit}();

        vm.prank(actor);
        try c.withdrawAll() {
            // Rule: after withdrawing everything previously credited, a fresh
            // deposit d followed by withdrawAll always succeeds and leaves the
            // contract holding nothing.
            assertTrue(address(c).balance == 0, "stale credit must not leak into later withdrawals");
        } catch {
            // The buggy version keeps the old credit (amount + d > balance d)
            // and underflows, reverting here.
            assertTrue(false, "withdrawAll must succeed for any caller whose credit is backed by the balance");
        }
    }
}

