pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // EOA so the payout call succeeds
        amount = bound(amount, 1, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // General rule: after a full cycle (deposit then withdrawAll), the
        // contract holds no residual ether and no outstanding credit for the
        // actor. The reference conserves ether exactly; the mutant's flipped
        // balance bookkeeping breaks the accounting invariant.
        assertTrue(address(c).balance == 0 && c.credit(actor) == 0);
    }
}

