pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = uint96(bound(uint256(amount), 1, 1e24));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // Invariant before withdrawal: contract holds exactly what was deposited.
        // Withdraw all credit; a correct contract pays out oCredit AND decrements
        // its internal accounting so contract balance equals deposits minus payouts.
        vm.prank(actor);
        c.withdrawAll();

        // After a full deposit+withdrawAll cycle the contract must retain nothing
        // beyond tracked net deposits (here: zero net).
        assertTrue(address(c).balance == 0, "contract balance must equal net deposits");
    }
}

